    fn ref_cache_http_parser_is_token(ch: c_uchar) -> bool {
        matches!(
            ch,
            b'!' | b'#'
                | b'$'
                | b'%'
                | b'&'
                | b'\''
                | b'*'
                | b'+'
                | b'-'
                | b'.'
                | b'0'..=b'9'
                | b'A'..=b'Z'
                | b'^'
                | b'_'
                | b'`'
                | b'a'..=b'z'
                | b'|'
                | b'~'
        )
    }

    fn ref_cache_hexval(ch: c_char) -> c_int {
        match ch as u8 {
            b'0'..=b'9' => (ch as u8 - b'0') as c_int,
            b'a'..=b'f' => (ch as u8 - b'a' + 10) as c_int,
            b'A'..=b'F' => (ch as u8 - b'A' + 10) as c_int,
            _ => -1,
        }
    }

