    // original: check_str2int (htslib/test/test_str2int.c:41)
    pub unsafe fn test_test_str2int_c_41_check_str2int(verbose: c_int) -> c_int {
        let mut buffer = [0 as c_char; 64];
        let mut end: *mut c_char = std::ptr::null_mut();
        let mut failed = 0;
        let sentinel = b'#' as c_char;

        for i in 1..64 {
            let num = (1u64 << i) - 1;
            let start_offset: i64 = if i < 5 { -(1_i64 << (i - 1)) } else { -16 };
            for offset in start_offset..=30 {
                let efail = (offset > 0) as c_int;
                let input = num.wrapping_add(offset as u64);
                libc::snprintf(
                    buffer.as_mut_ptr(),
                    buffer.len(),
                    c"%llu%c".as_ptr(),
                    input,
                    sentinel as c_int,
                );

                let uval = crate::htslib_mini_rs::hts::hts_str2uint(
                    buffer.as_ptr(),
                    &mut end,
                    i,
                    &mut failed,
                );
                let expected = if efail == 0 { input } else { num };
                if failed != efail || uval != expected || *end != sentinel {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2uint failed: %d bit %s %llu '%c' %d (%d)\n".as_ptr(),
                        i,
                        buffer.as_ptr(),
                        uval,
                        *end as c_int,
                        failed,
                        efail,
                    );
                    return -1;
                } else if verbose != 0 {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2uint OK: %d bit %s %llu '%c' %d (%d)\n".as_ptr(),
                        i,
                        buffer.as_ptr(),
                        uval,
                        *end as c_int,
                        failed,
                        efail,
                    );
                }
                failed = 0;
            }

            for offset in start_offset..=30 {
                let efail = (offset > 0) as c_int;
                let input = num.wrapping_add(offset as u64);
                libc::snprintf(
                    buffer.as_mut_ptr(),
                    buffer.len(),
                    c"%llu%c".as_ptr(),
                    input,
                    sentinel as c_int,
                );

                let val = crate::htslib_mini_rs::hts::hts_str2int(
                    buffer.as_ptr(),
                    &mut end,
                    i + 1,
                    &mut failed,
                );
                let expected = if efail == 0 { input as i64 } else { num as i64 };
                if failed != efail || val != expected || *end != sentinel {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2int  failed: %d bit %s %lld '%c' %d (%d)\n".as_ptr(),
                        i + 1,
                        buffer.as_ptr(),
                        val,
                        *end as c_int,
                        failed,
                        efail,
                    );
                    return -1;
                } else if verbose != 0 {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2int  OK: %d bit %s %lld '%c' %d (%d)\n".as_ptr(),
                        i + 1,
                        buffer.as_ptr(),
                        val,
                        *end as c_int,
                        failed,
                        efail,
                    );
                }
                failed = 0;
            }

            for offset in start_offset..=30 {
                let efail = (offset > 0) as c_int;
                let input = num.wrapping_add(offset as u64).wrapping_add(1);
                libc::snprintf(
                    buffer.as_mut_ptr(),
                    buffer.len(),
                    c"-%llu%c".as_ptr(),
                    input,
                    sentinel as c_int,
                );

                let val = crate::htslib_mini_rs::hts::hts_str2int(
                    buffer.as_ptr(),
                    &mut end,
                    i + 1,
                    &mut failed,
                );
                let expected = if efail == 0 {
                    input
                } else {
                    num.wrapping_add(1)
                };
                if failed != efail || (val as u64).wrapping_neg() != expected || *end != sentinel {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2int  failed: %d bit %s %lld '%c' %d (%d)\n".as_ptr(),
                        i + 1,
                        buffer.as_ptr(),
                        val,
                        *end as c_int,
                        failed,
                        efail,
                    );
                    return -1;
                } else if verbose != 0 {
                    libc::fprintf(
                        hts_sys::stderr.cast(),
                        c"hts_str2int  OK: %d bit %s %lld '%c' %d (%d)\n".as_ptr(),
                        i + 1,
                        buffer.as_ptr(),
                        val,
                        *end as c_int,
                        failed,
                        efail,
                    );
                }
                failed = 0;
            }
        }

        for offset in 0..=999 {
            let efail = (offset > 615) as c_int;
            libc::snprintf(
                buffer.as_mut_ptr(),
                buffer.len(),
                c"18446744073709551%03d%c".as_ptr(),
                offset,
                sentinel as c_int,
            );
            let uval = crate::htslib_mini_rs::hts::hts_str2uint(
                buffer.as_ptr(),
                &mut end,
                64,
                &mut failed,
            );
            let expected = if efail != 0 {
                u64::MAX
            } else {
                18_446_744_073_709_551_000u64 + offset as u64
            };
            if failed != efail || uval != expected || *end != sentinel {
                libc::fprintf(
                    hts_sys::stderr.cast(),
                    c"hts_str2uint failed: 64 bit %s %llu '%c' %d (%d)\n".as_ptr(),
                    buffer.as_ptr(),
                    uval,
                    *end as c_int,
                    failed,
                    efail,
                );
                return -1;
            } else if verbose != 0 {
                libc::fprintf(
                    hts_sys::stderr.cast(),
                    c"hts_str2uint OK: 64 bit %s %llu '%c' %d (%d)\n".as_ptr(),
                    buffer.as_ptr(),
                    uval,
                    *end as c_int,
                    failed,
                    efail,
                );
            }
        }

        0
    }

