    pub unsafe fn synced_bcf_reader_c_1060_regions_cmp(
        aptr: *const c_void,
        bptr: *const c_void,
    ) -> c_int {
        let a = aptr.cast::<SyncedBcfRegion1>();
        let b = bptr.cast::<SyncedBcfRegion1>();
        if (*a).start < (*b).start {
            -1
        } else if (*a).start > (*b).start {
            1
        } else if (*a).end < (*b).end {
            -1
        } else if (*a).end > (*b).end {
            1
        } else {
            0
        }
    }

