    // original: bcf_dec_typed_int1_safe (htslib/vcf.c:1918)
    pub unsafe fn vcf_c_1918_bcf_dec_typed_int1_safe(
        mut p: *mut c_uchar,
        end: *mut c_uchar,
        q: *mut *mut c_uchar,
        val: *mut i32,
    ) -> c_int {
        if end.offset_from(p) < 2 {
            return -1;
        }
        let t = (*p & 0x0f) as u32;
        p = p.add(1);
        if t == hts_sys::BCF_BT_INT8 {
            *val = *(p.cast::<i8>()) as i32;
            p = p.add(1);
        } else {
            let need = match t {
                x if x == hts_sys::BCF_BT_INT16 => 2,
                x if x == hts_sys::BCF_BT_INT32 => 4,
                x if x == hts_sys::BCF_BT_INT64 => 8,
                _ => return -1,
            };
            if end.offset_from(p) < need {
                return -1;
            }
            if t == hts_sys::BCF_BT_INT16 {
                *val = crate::htslib_mini_rs::hts::le_to_i16(p) as i32;
                p = p.add(2);
            } else if t == hts_sys::BCF_BT_INT32 {
                *val = crate::htslib_mini_rs::hts::le_to_i32(p);
                p = p.add(4);
            } else if t == hts_sys::BCF_BT_INT64 {
                *val = crate::htslib_mini_rs::hts::le_to_i64(p) as i32;
                p = p.add(8);
            }
        }
        *q = p;
        0
    }

    // original: bcf_dec_size_safe (htslib/vcf.c:1950)
    pub unsafe fn vcf_c_1950_bcf_dec_size_safe(
        p: *mut c_uchar,
        end: *mut c_uchar,
        q: *mut *mut c_uchar,
        num: *mut c_int,
        type_: *mut c_int,
    ) -> c_int {
        if p >= end {
            return -1;
        }
        *type_ = (*p & 0x0f) as c_int;
        if *p >> 4 != 15 {
            *q = p.add(1);
            *num = (*p >> 4) as c_int;
            return 0;
        }
        let r = vcf_c_1918_bcf_dec_typed_int1_safe(p.add(1), end, q, num);
        if r != 0 {
            return r;
        }
        (*num >= 0) as c_int - 1
    }

