                if !(res < 0
                    && (*crate::htslib_mini_rs::c_compat::__errno_location() == libc::EINTR
                        || *crate::htslib_mini_rs::c_compat::__errno_location() == libc::EAGAIN
                        || *crate::htslib_mini_rs::c_compat::__errno_location()
                            == libc::EWOULDBLOCK))
