        let mut ip6_seen = false;

        if (*opts).match_addrs.is_null() {
            return;
        }

        let slice = std::slice::from_raw_parts_mut((*opts).match_addrs, (*opts).num_match_addrs);
        slice.sort_by(|a, b| {
            let ip_order = if libc::AF_INET < libc::AF_INET6 {
                1
            } else {
                -1
            };
            let c = if a.family != b.family {
                ip_order * if a.family < b.family { -1 } else { 1 }
            } else {
                unsafe {
                    libc::memcmp(a.addr.as_ptr().cast(), b.addr.as_ptr().cast(), a.addr.len())
                }
            };
            c.cmp(&0)
        });

