            assert_eq!(
                functions::ref_cache_upstream_c_146_recv_cmd_data(
                    sockets[1],
                    got_md5.as_mut_ptr(),
                    &mut got_id,
                ),
                36
            );
            assert_eq!(std::ffi::CStr::from_ptr(got_md5.as_ptr()), md5);
            assert_eq!(got_id, 12345);

            let mut msg = TestRefCacheUpstreamMsgLayout {
                id: 77,
                code: 2,
                val: 9876,
            };
